// ===== Express CORS allowlist（生产推荐写法） =====
const allowedOrigins = new Set([
  'https://app.example.com',
  'https://admin.example.com'
]);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (origin && allowedOrigins.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin); // 必须是明确 Origin，不能用 *
    res.setHeader('Vary', 'Origin');                        // 防止 CDN 缓存串源
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,PATCH');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type,Authorization');
    res.setHeader('Access-Control-Max-Age', '600');         // 预检结果缓存 10 分钟
  }
  if (req.method === 'OPTIONS') return res.sendStatus(204); // 预检请求直接返回，不进入业务逻辑
  next();
});

// ===== Fetch 正确用法：凭证 + 错误处理 + 超时 =====
const controller = new AbortController();
const timeoutId = setTimeout(() => controller.abort(), 5000); // 5 秒超时

try {
  const response = await fetch('/api/data', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',           // 带 Cookie
    signal: controller.signal,         // 超时/取消
    body: JSON.stringify({ key: 'value' })
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`); // 4xx/5xx 需手动检查
  const data = await response.json();
} finally {
  clearTimeout(timeoutId);
}
